procedure BounceRefunds {
  about "Handle rain cancellations within limits"
  policy BouncePolicy
  sheet Cancels "Cancels" { rental_id: Text, renter: Text, deposit: Money }
  trigger when new row r in Cancels

  if r.deposit <= $30.00 {
    refund r.deposit for r.rental_id reason "rain cancellation", ask owner first timeout 6 hours else skip
  } else if r.deposit > $30.00 and r.deposit <= $120.00 {
    refund r.deposit for r.rental_id reason "rain cancellation", ask owner first timeout 6 hours else skip
  } else {
    notify owner "Refund request for {r.rental_id} is over $120. Please review."
    stop "over refund limit"
  }
}
```

