procedure OrchardOrderItems {
  about "Place daily stock orders"
  policy OrchardPolicy
  sheet Stock "Stock" { item: Text, crates: Number, minimum: Number, reorder_crates: Number, supplier: Text, crate_price: Money }
  trigger every morning at 06:30

  let all = fetch Stock
  for each r in all where r.crates < r.minimum {
    let order_amount = min(r.reorder_crates, r.crates - r.minimum)
    if order_amount * r.crate_price > $200.00 {
      notify owner "Cannot place order for {r.item}: total cost exceeds $200."
      continue
    }
    order r.item { crates: order_amount, at: today() }
    send "placed order for {r.item} with {order_amount} crates at {today()}."
  }
}
```

