procedure SewReminderBatch {
  about "Send reminders to enrolled students two days before a class"
  policy SewPolicy
  sheet Students "Students" { student: Text, email: Email, phone: Phone, class_at: DateTime, class_name: Text, paid: Bool, status: Text, measurements: Text private }
  trigger every day at 9:00

  let all = fetch Students
  let due = filter all where status == "enrolled" and days_between(class_at, today()) == 2
  let n = summarize count of due
  append Outreach { day: today() - 2, campaign: "bring fabric scissors", targeted: n }
  let msgs = draft each r in due up to 30 sms to r.email: "Hi {r.student default 'there'}, please bring fabric scissors for the class on {class_at}."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
}

