procedure TreePickupInfo {
  about "Notify customers about upcoming tree pickup"
  policy TreePolicy
  sheet TreeOrders "TreeOrders" { buyer: Text, phone: Phone, email: Email, tree_size: Text, delivery_at: DateTime, status: Text, drop_notes: Text private }
