procedure CheeseReorders {
  about "Order wheels when stock falls below minimum"
  policy CheesePolicy
  sheet Wheels "Wheels" { cheese: Text, on_hand: Number, minimum: Number, reorder_qty: Number, maker: Text, unit_cost: Money }
  trigger every Thursday at 06:00

  let all = fetch Wheels
  let low_stock = filter all where on_hand < minimum
  for each r in low_stock up to 5 {
    if r.unit_cost * r.on_hand > $150.00 {
      notify owner "Wheel order {r.cheese} is above $150. Please review."
      stop "over order limit"
    }
    order r.cheese for r.reorder_qty from r.maker
  }
}
```

