procedure PlanetShowSchedule {
  about "Tweet upcoming shows"
  policy PlanetPolicy
  sheet Shows "Shows" { title: Text, show_at: DateTime, seats: Number, sold: Number }
  trigger every monday at 09:00

  let today = today()
